import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class IpifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('ipMtu', '1500')
        self.set_interfaceDN()

    def set_interfaceDN(self):
        bts_id = self.enb_ent_config['id']
        srch = re.search(r'TNL-(\d+)/IPNO-1/IPIF-(\d+)', self.dist_name)
        tnl_num = srch.group(1)
        if_num = srch.group(2)
        self.set_parameter('interfaceDN', f'MRBTS-{bts_id}/TNLSVC-1/TNL-{tnl_num}/ETHSVC-1/ETHIF-1/VLANIF-{if_num}')
